{
  let ciPassed = 0, ciFailed = 0
  const ciAssert = (c, m) => { if (c) ciPassed++; else { ciFailed++; console.log(`  FAIL: ${m}`) } }

  const analyzer = new mod.CodeIntentAnalyzer()

  // CI-1: analyze returns CodeIntentMap structure
  const result = await analyzer.analyze("test", "/tmp")
  ciAssert(Array.isArray(result.files), "CI-1a: files is array")
  ciAssert(typeof result.goal === "string", "CI-1b: goal is string")
  ciAssert(typeof result.projectDir === "string", "CI-1c: projectDir is string")
  ciAssert(typeof result.analysisTimestamp === "number", "CI-1d: timestamp is number")
  ciAssert(Array.isArray(result.dependencyChain), "CI-1e: dependencyChain is array")
  ciAssert(typeof result.overallSummary === "string", "CI-1f: overallSummary is string")

  // CI-2: getContextSummary returns XML
  const summary = analyzer.getContextSummary(result)
  ciAssert(summary.includes("<code-intent-analysis>"), "CI-2a: XML opening tag")
  ciAssert(summary.includes("</code-intent-analysis>"), "CI-2b: XML closing tag")

  // CI-3: getCompactSummary returns text
  const compact = analyzer.getCompactSummary(result)
  ciAssert(compact.includes("[Code Intent:"), "CI-3a: compact summary starts with code intent")

  // CI-4: empty result getContextSummary
  const emptyResult = { goal: "test", projectDir: "/tmp", primaryLanguage: null, files: [], dependencyChain: [], overallSummary: "", analysisTimestamp: 0 }
  ciAssert(analyzer.getContextSummary(emptyResult) === "", "CI-4a: empty context summary")
  ciAssert(analyzer.getCompactSummary(emptyResult) === "", "CI-4b: empty compact summary")

  // CI-5: analyze with project dir that has no navigator (no crash)
  const result3 = await analyzer.analyze("nonexistent goal", "/nonexistent")
  ciAssert(Array.isArray(result3.files), "CI-5a: returns valid structure even without navigator")
  ciAssert(result3.files.length === 0, "CI-5b: no files found")

  // CI-6: getContextSummary with maxFiles
  const ctx2 = analyzer.getContextSummary(result, 1)
  ciAssert(ctx2.includes("<file"), "CI-6a: context summary with maxFiles=1")

  // CI-7: invalidateCache doesn't throw
  analyzer.invalidateCache()
  ciAssert(true, "CI-7a: invalidateCache runs without error")

  console.log(`  CodeIntentAnalyzer: ${ciPassed} passed, ${ciFailed} failed`)
  passed += ciPassed; failed += ciFailed
}

